package com.bank.recognition;

import java.util.*;
import java.util.logging.*;
import static java.util.stream.Collectors.*;

public class RecognitionDemo {
    private static final Logger log = Logger.getLogger("Recognition");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee(1L, "Rajesh", "IT", 95000.0),
            new Employee(2L, "Priya", "Finance", 250000.0),
            new Employee(3L, "Amit", "IT", 120000.0),
            new Employee(4L, "Sneha", "Finance", 180000.0)
        );
        RecognitionService service = new RecognitionService();
        Map<String, Employee> top = service.topEarnerByDepartment(staff);
        top.forEach((dept, e) -> log.info(() ->
            dept + " top earner -> " + e.getName() + " (" + e.getSalary() + ")"));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final Long id;
    private final String name;
    private final String department;
    private final double salary;
    Employee(Long id, String name, String department, double salary) {
        this.id = id; this.name = name; this.department = department; this.salary = salary;
    }
    String getName() { return name; }
    String getDepartment() { return department; }
    double getSalary() { return salary; }
}

// ─── Would be in service/RecognitionService.java ───
class RecognitionService {
    // maxBy → Optional per group; collectingAndThen + Optional::get unwraps to Employee.
    Map<String, Employee> topEarnerByDepartment(List<Employee> employees) {
        return employees.stream()
            .collect(groupingBy(Employee::getDepartment, TreeMap::new,
                collectingAndThen(
                    maxBy(Comparator.comparingDouble(Employee::getSalary)),
                    Optional::get)));
    }
}
